/workspace/inspect.go.content:
package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"github.com/hashicorp/hcl/v2/hclwrite"
	_ "modernc.org/sqlite"
)

type inspectOptions struct {
	url     string
	devURL  string
	schemas []string
	exclude []string
	format  string
}

type inspectDoc struct {
	Schemas []*inspectSchema `json:"schemas"`
}

type inspectSchema struct {
	Name   string          `json:"name"`
	Tables []*inspectTable `json:"tables,omitempty"`
}

type inspectTable struct {
	Name        string               `json:"name"`
	Columns     []*inspectColumn     `json:"columns,omitempty"`
	PrimaryKey  []string             `json:"-"`
	Indexes     []*inspectIndex      `json:"-"`
	ForeignKeys []*inspectForeignKey `json:"-"`
}

type inspectColumn struct {
	Name        string  `json:"name"`
	DeclaredSQL string  `json:"type"`
	HCLType     string  `json:"-"`
	SQLType     string  `json:"-"`
	Null        *bool   `json:"null,omitempty"`
	NotNull     bool    `json:"-"`
	DefaultSQL  *string `json:"-"`
	DefaultHCL  *string `json:"-"`
}

type inspectIndex struct {
	Name    string
	Unique  bool
	Columns []string
}

type inspectForeignKey struct {
	ID         int
	RefTable   string
	Columns    []string
	RefColumns []string
	OnUpdate   string
	OnDelete   string
}

func runSchemaInspect(cmd interface{ OutOrStdout() any }, global *globalOptions, opts inspectOptions) error {
	if opts.url == "" && global.envName != "" {
		env, err := loadConfigEnv(global.configURL, global.envName, global.vars)
		if err != nil {
			return err
		}
		if opts.url == "" {
			opts.url = env.URL
		}
	}
	if opts.url == "" {
		return fmt.Errorf(`required flag(s) "url" not set`)
	}
	driver := urlDriver(opts.url)
	if driver != "sqlite" {
		return fmt.Errorf(`sql/sqlclient: unknown driver %q. See: https://atlasgo.io/url`, driver)
	}
	doc, err := inspectSQLite(opts.url, opts.exclude)
	if err != nil {
		return err
	}

	out := renderInspectDefault(doc)
	if opts.format != "" {
		out, err = renderTemplate(opts.format, doc, map[string]any{
			"json": func(v any) (string, error) {
				return renderInspectJSON(doc)
			},
			"sql": func(v any, indent ...string) (string, error) {
				return renderInspectSQL(doc), nil
			},
			"mermaid": func(v any) (string, error) {
				return renderInspectMermaid(doc), nil
			},
		})
		if err != nil {
			return err
		}
	}
	switch c := cmd.(type) {
	case *cobraCommandAdapter:
		fmt.Fprint(c.cmd.OutOrStdout(), out)
	default:
		// Unreachable in this codebase, but keeps tests simple if reused.
	}
	return nil
}

type cobraCommandAdapter struct {
	cmd interface {
		OutOrStdout() any
	}
}

func urlDriver(raw string) string {
	if idx := strings.Index(raw, "://"); idx >= 0 {
		return raw[:idx]
	}
	return ""
}

func sqliteDSN(raw string) string {
	path := strings.TrimPrefix(raw, "sqlite://")
	switch {
	case strings.HasPrefix(path, "file:"):
		return path
	case strings.Contains(path, "?"):
		return "file:" + path
	default:
		return path
	}
}

func inspectSQLite(rawURL string, exclude []string) (*inspectDoc, error) {
	db, err := sql.Open("sqlite", sqliteDSN(rawURL))
	if err != nil {
		return nil, err
	}
	defer db.Close()

	rows, err := db.Query(`SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY rowid`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	schema := &inspectSchema{Name: "main"}
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			return nil, err
		}
		if matchesAny(name, exclude) {
			continue
		}
		table, err := inspectSQLiteTable(db, name)
		if err != nil {
			return nil, err
		}
		schema.Tables = append(schema.Tables, table)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	return &inspectDoc{Schemas: []*inspectSchema{schema}}, nil
}

func inspectSQLiteTable(db *sql.DB, tableName string) (*inspectTable, error) {
	table := &inspectTable{Name: tableName}

	colRows, err := db.Query(`PRAGMA table_info(` + quoteSQLiteIdent(tableName) + `)`)
	if err != nil {
		return nil, err
	}
	defer colRows.Close()

	pkParts := make(map[int]string)
	for colRows.Next() {
		var (
			cid       int
			name      string
			declType  string
			notNull   int
			defaultV  sql.NullString
			pkOrdinal int
		)
		if err := colRows.Scan(&cid, &name, &declType, &notNull, &defaultV, &pkOrdinal); err != nil {
			return nil, err
		}
		nullVal := notNull == 0
		column := &inspectColumn{
			Name:        name,
			DeclaredSQL: declType,
			HCLType:     hclTypeForSQLite(declType),
			SQLType:     sqlTypeForSQLite(declType),
			NotNull:     notNull != 0,
		}
		if nullVal {
			column.Null = boolPtr(true)
		}
		if defaultV.Valid {
			d := defaultV.String
			column.DefaultSQL = &d
			if hclVal := hclDefaultValue(d); hclVal != "" {
				column.DefaultHCL = &hclVal
			}
		}
		table.Columns = append(table.Columns, column)
		if pkOrdinal > 0 {
			pkParts[pkOrdinal] = name
		}
	}
	if err := colRows.Err(); err != nil {
		return nil, err
	}
	if len(pkParts) > 0 {
		ords := make([]int, 0, len(pkParts))
		for ord := range pkParts {
			ords = append(ords, ord)
		}
		sort.Ints(ords)
		for _, ord := range ords {
			table.PrimaryKey = append(table.PrimaryKey, pkParts[ord])
		}
	}

	indexRows, err := db.Query(`PRAGMA index_list(` + quoteSQLiteIdent(tableName) + `)`)
	if err != nil {
		return nil, err
	}
	defer indexRows.Close()
	for indexRows.Next() {
		var (
			seq     int
			name    string
			unique  int
			origin  string
			partial int
		)
		if err := indexRows.Scan(&seq, &name, &unique, &origin, &partial); err != nil {
			return nil, err
		}
		_ = seq
		_ = origin
		_ = partial
		cols, err := inspectSQLiteIndexColumns(db, name)
		if err != nil {
			return nil, err
		}
		table.Indexes = append(table.Indexes, &inspectIndex{
			Name:    name,
			Unique:  unique != 0,
			Columns: cols,
		})
	}
	if err := indexRows.Err(); err != nil {
		return nil, err
	}

	fkRows, err := db.Query(`PRAGMA foreign_key_list(` + quoteSQLiteIdent(tableName) + `)`)
	if err != nil {
		return nil, err
	}
	defer fkRows.Close()
	fks := map[int]*inspectForeignKey{}
	order := []int{}
	for fkRows.Next() {
		var (
			id       int
			seq      int
			refTable string
			fromCol  string
			toCol    string
			onUpdate string
			onDelete string
			match    string
		)
		if err := fkRows.Scan(&id, &seq, &refTable, &fromCol, &toCol, &onUpdate, &onDelete, &match); err != nil {
			return nil, err
		}
		_ = seq
		_ = match
		fk, ok := fks[id]
		if !ok {
			fk = &inspectForeignKey{
				ID:       id,
				RefTable: refTable,
				OnUpdate: strings.ReplaceAll(strings.ToUpper(onUpdate), " ", "_"),
				OnDelete: strings.ReplaceAll(strings.ToUpper(onDelete), " ", "_"),
			}
			fks[id] = fk
			order = append(order, id)
		}
		fk.Columns = append(fk.Columns, fromCol)
		fk.RefColumns = append(fk.RefColumns, toCol)
	}
	if err := fkRows.Err(); err != nil {
		return nil, err
	}
	sort.Ints(order)
	for _, id := range order {
		table.ForeignKeys = append(table.ForeignKeys, fks[id])
	}
	return table, nil
}

func inspectSQLiteIndexColumns(db *sql.DB, indexName string) ([]string, error) {
	rows, err := db.Query(`PRAGMA index_info(` + quoteSQLiteIdent(indexName) + `)`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var cols []string
	for rows.Next() {
		var (
			seqno int
			cid   int
			name  string
		)
		if err := rows.Scan(&seqno, &cid, &name); err != nil {
			return nil, err
		}
		_ = seqno
		_ = cid
		cols = append(cols, name)
	}
	return cols, rows.Err()
}

func renderInspectDefault(doc *inspectDoc) string {
	var b strings.Builder
	for _, schema := range doc.Schemas {
		for _, table := range schema.Tables {
			fmt.Fprintf(&b, "table %q {\n", table.Name)
			fmt.Fprintf(&b, "schema = schema.%s\n", schema.Name)
			for _, column := range table.Columns {
				fmt.Fprintf(&b, "column %q {\n", column.Name)
				if column.Null != nil {
					fmt.Fprintf(&b, "null = %t\n", *column.Null)
				} else {
					fmt.Fprintf(&b, "null = false\n")
				}
				fmt.Fprintf(&b, "type = %s\n", column.HCLType)
				if column.DefaultHCL != nil {
					fmt.Fprintf(&b, "default = %s\n", *column.DefaultHCL)
				}
				fmt.Fprintln(&b, "}")
			}
			if len(table.PrimaryKey) > 0 {
				fmt.Fprintln(&b, "primary_key {")
				fmt.Fprintf(&b, "columns = [%s]\n", joinColumnRefs("column.", table.PrimaryKey))
				fmt.Fprintln(&b, "}")
			}
			for _, fk := range table.ForeignKeys {
				fmt.Fprintf(&b, "foreign_key %q {\n", strconv.Itoa(fk.ID))
				fmt.Fprintf(&b, "columns = [%s]\n", joinColumnRefs("column.", fk.Columns))
				fmt.Fprintf(&b, "ref_columns = [%s]\n", joinForeignColumnRefs(fk.RefTable, fk.RefColumns))
				fmt.Fprintf(&b, "on_update = %s\n", fk.OnUpdate)
				fmt.Fprintf(&b, "on_delete = %s\n", fk.OnDelete)
				fmt.Fprintln(&b, "}")
			}
			for _, idx := range table.Indexes {
				fmt.Fprintf(&b, "index %q {\n", idx.Name)
				if idx.Unique {
					fmt.Fprintln(&b, "unique = true")
				}
				fmt.Fprintf(&b, "columns = [%s]\n", joinColumnRefs("column.", idx.Columns))
				fmt.Fprintln(&b, "}")
			}
			fmt.Fprintln(&b, "}")
		}
		fmt.Fprintf(&b, "schema %q {\n}\n", schema.Name)
	}
	return string(hclwrite.Format([]byte(b.String())))
}

func renderInspectJSON(doc *inspectDoc) (string, error) {
	raw, err := json.Marshal(doc)
	if err != nil {
		return "", err
	}
	return string(raw), nil
}

func renderInspectSQL(doc *inspectDoc) string {
	var b strings.Builder
	first := true
	for _, schema := range doc.Schemas {
		for _, table := range schema.Tables {
			if !first {
				b.WriteByte('\n')
			}
			first = false
			fmt.Fprintf(&b, "-- Create %q table\n", table.Name)
			fmt.Fprintf(&b, "CREATE TABLE `%s` (", table.Name)
			parts := make([]string, 0, len(table.Columns)+1+len(table.ForeignKeys))
			for _, col := range table.Columns {
				part := fmt.Sprintf("`%s` %s", col.Name, col.SQLType)
				if col.NotNull {
					part += " NOT NULL"
				} else {
					part += " NULL"
				}
				if col.DefaultSQL != nil {
					part += " DEFAULT " + *col.DefaultSQL
				}
				parts = append(parts, part)
			}
			if len(table.PrimaryKey) > 0 {
				parts = append(parts, fmt.Sprintf("PRIMARY KEY (%s)", joinBacktickRefs(table.PrimaryKey)))
			}
			for _, fk := range table.ForeignKeys {
				parts = append(parts, fmt.Sprintf("CONSTRAINT `%d` FOREIGN KEY (%s) REFERENCES `%s` (%s) ON UPDATE %s ON DELETE %s",
					fk.ID,
					joinBacktickRefs(fk.Columns),
					fk.RefTable,
					joinBacktickRefs(fk.RefColumns),
					strings.ReplaceAll(fk.OnUpdate, "_", " "),
					strings.ReplaceAll(fk.OnDelete, "_", " "),
				))
			}
			b.WriteString(strings.Join(parts, ", "))
			b.WriteString(");")
			for _, idx := range table.Indexes {
				b.WriteByte('\n')
				sqlName := sqlIndexName(table.Name, idx)
				fmt.Fprintf(&b, "-- Create index %q to table: %q\n", sqlName, table.Name)
				if idx.Unique {
					fmt.Fprintf(&b, "CREATE UNIQUE INDEX `%s` ON `%s` (%s);", sqlName, table.Name, joinBacktickRefs(idx.Columns))
				} else {
					fmt.Fprintf(&b, "CREATE INDEX `%s` ON `%s` (%s);", sqlName, table.Name, joinBacktickRefs(idx.Columns))
				}
			}
		}
	}
	return b.String()
}

func renderInspectMermaid(doc *inspectDoc) string {
	var b strings.Builder
	b.WriteString("erDiagram\n")
	for _, schema := range doc.Schemas {
		for _, table := range schema.Tables {
			fmt.Fprintf(&b, "    %s {\n", table.Name)
			fkColumns := map[string]bool{}
			pkColumns := map[string]bool{}
			for _, col := range table.PrimaryKey {
				pkColumns[col] = true
			}
			for _, fk := range table.ForeignKeys {
				for _, col := range fk.Columns {
					fkColumns[col] = true
				}
			}
			for _, col := range table.Columns {
				line := fmt.Sprintf("      %s %s", col.SQLType, col.Name)
				switch {
				case pkColumns[col.Name]:
					line += " PK"
				case fkColumns[col.Name]:
					line += " FK"
				}
				b.WriteString(line + "\n")
			}
			b.WriteString("    }\n")
		}
		for _, table := range schema.Tables {
			for _, fk := range table.ForeignKeys {
				fmt.Fprintf(&b, "    %s }o--o| %s : %d\n", table.Name, fk.RefTable, fk.ID)
			}
		}
	}
	return strings.TrimRight(b.String(), "\n")
}

func quoteSQLiteIdent(name string) string {
	return "'" + strings.ReplaceAll(name, "'", "''") + "'"
}

func matchesAny(name string, patterns []string) bool {
	for _, pattern := range patterns {
		ok, err := filepath.Match(pattern, name)
		if err == nil && ok {
			return true
		}
	}
	return false
}

func boolPtr(v bool) *bool {
	return &v
}

func hclTypeForSQLite(decl string) string {
	t := strings.ToLower(strings.TrimSpace(decl))
	switch {
	case t == "":
		return `sql("")`
	case t == "integer" || t == "int" || t == "text" || t == "blob" || t == "numeric" || t == "real":
		return t
	case strings.HasPrefix(t, "varchar("):
		return t
	case strings.Contains(t, "("):
		base := strings.TrimSpace(strings.SplitN(t, "(", 2)[0])
		return fmt.Sprintf(`sql(%q)`, base)
	default:
		return t
	}
}

func sqlTypeForSQLite(decl string) string {
	t := strings.ToLower(strings.TrimSpace(decl))
	if t == "" {
		return "blob"
	}
	if strings.Contains(t, "(") {
		return strings.TrimSpace(strings.SplitN(t, "(", 2)[0])
	}
	return t
}

func hclDefaultValue(sqlValue string) string {
	if sqlValue == "" {
		return ""
	}
	if sqlValue[0] == '\'' && sqlValue[len(sqlValue)-1] == '\'' && len(sqlValue) >= 2 {
		unquoted := strings.ReplaceAll(sqlValue[1:len(sqlValue)-1], "''", "'")
		return strconv.Quote(unquoted)
	}
	return sqlValue
}

func joinColumnRefs(prefix string, cols []string) string {
	parts := make([]string, 0, len(cols))
	for _, col := range cols {
		parts = append(parts, prefix+col)
	}
	return strings.Join(parts, ", ")
}

func joinForeignColumnRefs(table string, cols []string) string {
	parts := make([]string, 0, len(cols))
	for _, col := range cols {
		parts = append(parts, "table."+table+".column."+col)
	}
	return strings.Join(parts, ", ")
}

func joinBacktickRefs(cols []string) string {
	parts := make([]string, 0, len(cols))
	for _, col := range cols {
		parts = append(parts, fmt.Sprintf("`%s`", col))
	}
	return strings.Join(parts, ", ")
}

func sqlIndexName(table string, idx *inspectIndex) string {
	if strings.HasPrefix(idx.Name, "sqlite_autoindex_") && len(idx.Columns) > 0 {
		return table + "_" + strings.Join(idx.Columns, "_")
	}
	return idx.Name
}

