	cmd.Flags().StringSliceVarP(&schemas, "schema", "s", nil, "set schema names")
	cmd.Flags().StringVar(&devURL, "dev-url", "", "[driver://username:password@address/dbname?param=value] select a dev database using the URL format")
	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "print SQL without executing it")
	cmd.Flags().BoolVar(&autoApprove, "auto-approve", false, "apply changes without prompting for approval")
	cmd.Flags().StringVar(&format, "format", "", "Go template to use to format the output")
	cmd.Flags().StringVar(&txMode, "tx-mode", "file", "set transaction mode [none, file]")
	cmd.Flags().StringVar(&planURL, "plan", "", "URL to a pre-planned migration (e.g., atlas://repo/plans/name)")
