	cmd.PersistentFlags().StringVar(&opts.envName, "env", "", "set which env from the config file to use")
	cmd.PersistentFlags().StringArrayVar(&opts.vars, "var", nil, "input variables")
}

func unsupportedRun(name string) func(cmd *cobra.Command, args []string) error {
	return func(cmd *cobra.Command, args []string) error {
		return errors.New(name + " is not implemented in this reimplementation")
	}
}

func renderTemplate(tmplText string, data any, funcs template.FuncMap) (string, error) {
	tmpl, err := template.New("format").Funcs(funcs).Parse(tmplText)
	if err != nil {
		return "", err
	}
	var b strings.Builder
	if err := tmpl.Execute(&b, data); err != nil {
		return "", err
	}
	return b.String(), nil
}

func maybeEditFile(path string) error {
	editor := os.Getenv("VISUAL")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		return nil
	}
	fields := strings.Fields(editor)
	if len(fields) == 0 {
		return nil
	}
	cmd := exec.Command(fields[0], append(fields[1:], path)...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

