package main

import (
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/hashicorp/hcl/v2"
	"github.com/hashicorp/hcl/v2/hclparse"
	"github.com/zclconf/go-cty/cty"
	"github.com/zclconf/go-cty/cty/function"
)

type configEnv struct {
	URL     string
	DevURL  string
	Schemas []string
}

func loadConfigEnv(configURL, envName string, rawVars []string) (*configEnv, error) {
	path := fileURLPath(configURL)
	if _, err := os.Stat(path); err != nil {
		return nil, fmt.Errorf("config file %q was not found: %w", path, err)
	}

	parser := hclparse.NewParser()
	file, diags := parser.ParseHCLFile(path)
	if diags.HasErrors() {
		return nil, diags
	}

	schema := &hcl.BodySchema{
		Blocks: []hcl.BlockHeaderSchema{
			{Type: "variable", LabelNames: []string{"name"}},
			{Type: "locals"},
			{Type: "env", LabelNames: []string{"name"}},
		},
	}
	content, diags := file.Body.Content(schema)
	if diags.HasErrors() {
		return nil, diags
	}

	overrides := parseVarOverrides(rawVars)
	_jsiiVars, err := evalVariables(content.Blocks, overrides, envName)
	if err != nil {
		return nil, err
	}
	locals, err := evalLocals(content.Blocks, _jsiiVars, envName)
	if err != nil {
		return nil, err
	}

	var selected *hcl.Block
	for _, block := range content.Blocks {
		if block.Type == "env" && len(block.Labels) > 0 && block.Labels[0] == envName {
			selected = block
			break
		}
	}
	if selected == nil {
		return nil, fmt.Errorf("env %q not defined in config file", envName)
	}

	attrs, diags := selected.Body.JustAttributes()
	if diags.HasErrors() {
		return nil, diags
	}
	ctx := evalContext(_jsiiVars, locals, envName)

	env := &configEnv{}
	if attr, ok := attrs["url"]; ok {
		value, diags := attr.Expr.Value(ctx)
		if diags.HasErrors() {
			return nil, diags
		}
		if value.Type() == cty.String {
			env.URL = value.AsString()
		}
	}
	if attr, ok := attrs["dev"]; ok {
		value, diags := attr.Expr.Value(ctx)
		if diags.HasErrors() {
			return nil, diags
		}
		if value.Type() == cty.String {
			env.DevURL = value.AsString()
		}
	}
	if attr, ok := attrs["schemas"]; ok {
		value, diags := attr.Expr.Value(ctx)
		if diags.HasErrors() {
			return nil, diags
		}
		if value.Type().IsTupleType() || value.Type().IsListType() || value.Type().IsSetType() {
			it := value.ElementIterator()
			for it.Next() {
				_, v := it.Element()
				if v.Type() == cty.String {
					env.Schemas = append(env.Schemas, v.AsString())
				}
			}
		}
	}

	return env, nil
}

func parseVarOverrides(raw []string) map[string]string {
	out := make(map[string]string, len(raw))
	for _, item := range raw {
		parts := strings.SplitN(item, "=", 2)
		if len(parts) == 2 {
			out[parts[0]] = parts[1]
		}
	}
	return out
}

func evalVariables(blocks hcl.Blocks, overrides map[string]string, envName string) (map[string]cty.Value, error) {
	values := make(map[string]cty.Value)
	for _, block := range blocks {
		if block.Type != "variable" || len(block.Labels) == 0 {
			continue
		}
		name := block.Labels[0]
		if override, ok := overrides[name]; ok {
			values[name] = cty.StringVal(override)
			continue
		}
		attrs, diags := block.Body.JustAttributes()
		if diags.HasErrors() {
			return nil, diags
		}
		attr, ok := attrs["default"]
		if !ok {
			return nil, fmt.Errorf("missing value for required variable %q", name)
		}
		value, diags := attr.Expr.Value(evalContext(values, nil, envName))
		if diags.HasErrors() {
			return nil, diags
		}
		values[name] = value
	}
	return values, nil
}

func evalLocals(blocks hcl.Blocks, vars map[string]cty.Value, envName string) (map[string]cty.Value, error) {
	locals := make(map[string]cty.Value)
	for _, block := range blocks {
		if block.Type != "locals" {
			continue
		}
		attrs, diags := block.Body.JustAttributes()
		if diags.HasErrors() {
			return nil, diags
		}
		keys := make([]string, 0, len(attrs))
		for key := range attrs {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			value, diags := attrs[key].Expr.Value(evalContext(vars, nil, envName))
			if diags.HasErrors() {
				return nil, diags
			}
			locals[key] = value
		}
	}
	return locals, nil
}

func evalContext(vars, locals map[string]cty.Value, envName string) *hcl.EvalContext {
	ctx := &hcl.EvalContext{
		Functions: map[string]function.Function{
			"getenv": function.New(&function.Spec{
				Params: []function.Parameter{
					{Name: "name", Type: cty.String},
				},
				Type: function.StaticReturnType(cty.String),
				Impl: func(args []cty.Value, retType cty.Type) (cty.Value, error) {
					return cty.StringVal(os.Getenv(args[0].AsString())), nil
				},
			}),
		},
		Variables: map[string]cty.Value{
			"atlas": cty.ObjectVal(map[string]cty.Value{
				"env": cty.StringVal(envName),
			}),
		},
	}
	if vars != nil {
		ctx.Variables["var"] = cty.ObjectVal(vars)
	}
	if locals != nil {
		ctx.Variables["local"] = cty.ObjectVal(locals)
	}
	return ctx
}

func fileURLPath(raw string) string {
	if strings.HasPrefix(raw, "file://") {
		return strings.TrimPrefix(raw, "file://")
	}
	return raw
}

